extension ls {
  func printcol(_ dp : DISPLAY) {
    //    static FTSENT **array;
    //    static int lastentries = -1;
    //    FTSENT *p;
    //    FTSENT **narray;
    //    int base;
    //    int chcnt;
    //    int cnt;
    //    int col;
    //    int colwidth;
    //    int endcol;
    //    int num;
    //    int numcols;
    //    int numrows;
    //    int row;

    var tabwidth = r.f_notabs ? 1 : 8

    /*
     * Have to do random access in the linked list -- build a table
     * of pointers.
     */
//    if r.lastentries == -1 || dp.entries > r.lastentries {
//      lastentries = dp.entries
//    }

    r.array = dp.list ?? []

    var colwidth = dp.maxlen
    if options.f_inode {
      colwidth += dp.s_inode + 1
    }
    if options.f_size {
      colwidth += dp.s_block + 1
    }
    if (options.f_type) {
      colwidth += 1;
    }

    colwidth = UInt((Int(colwidth) + tabwidth) & ~(tabwidth - 1))
    if options.termwidth < 2 * colwidth {
      printscol(dp)
      return
    }
    var numcols = options.termwidth / Int(colwidth)
    var numrows = r.array.count / numcols
    if 0 != (r.array.count % numcols) {
      numrows += 1
    }

    if (dp.list == nil || dp.list!.isEmpty || dp.list![0].level != CMigration.FTS_ROOTLEVEL) &&
        (options.f_longform || options.f_size) {
      print("total %qu", howmany(Int(dp.btotal), Int(options.blocksize)))
    }

    var base = 0;
    for row in 0 ..< numrows {
      var endcol = colwidth
      if !options.f_sortacross {
        base = row
      }
      var chcnt = 0
      for col in 0 ..< numcols {
        assert(base < r.array.count)
        chcnt += printaname(r.array[base], Int(dp.s_inode), Int(dp.s_block))
        if options.f_sortacross {
          base += 1
        }
        else {
          base += numrows
        }
        if base >= r.array.count {
          break
        }
        while true {
          let cnt = ((chcnt + tabwidth) & ~(tabwidth - 1))
          if cnt > endcol { break }
          if options.f_sortacross && col + 1 >= numcols {
            break
          }
          putchar(r.f_notabs ? Int32(0x20) : Int32(0x0a) )
          chcnt = cnt;
        }
        endcol += colwidth
      }
      print("")
    }
  }

  /*
   * print [inode] [size] name
   * return # of characters printed, no trailing characters.
   */
  func printaname(_ p : FTSEntry, _ inodefield : Int, _ sizefield : Int) -> Int {
    var color_printed = false
    let sp = p.statp
    var chcnt = 0
    if options.f_inode {
      print(String(sp.inode).leftPad(toLength: Int(inodefield)), terminator: " ")
      chcnt += 1 + inodefield
    }
    if options.f_size {
      print(String(howmany(Int(sp.blocks), Int(options.blocksize))).leftPad(toLength: Int(sizefield)), terminator: " ")
      chcnt += 1 + sizefield
    }

    if options.f_color {
      color_printed = colortype(sp.filetype, sp.permissions, sp.flags)
    }

    chcnt += printname(p.name)

    if options.f_color && color_printed {
      endcolor(0)
    }

    if options.f_type {
      chcnt += printtype(sp.filetype, sp.permissions)
    }
    return chcnt
  }

  /*
   * Print device special file major and minor numbers.
   */
  func printdev(_ width: size_t, _ dev : dev_t) {
    let x = cFormat("%#*jx ", width, dev)
    print(x, terminator: "")
  }

  func ls_strftime(_ fmtx : String, _ tm : tm?) -> String {
//    char *posb, nfmt[BUFSIZ];
//    const char *format = fmt;
//    size_t ret;

    var fmt : String = fmtx
    guard let tm else {

      /*
       * rdar://problem/9977017 - Fill str with ? if localtime() had
       * returned NULL.  This is better than crashing as we try to
       * dereference it, though it doesn't always look the nicest.
       */
      return fmt.replacing(/[^ ]/, with: "?")
    }

    if let posb = fmt.ranges(of: "%b").first {
      if r.month_max_size == 0 {
        compute_abbreviated_month_size()
      }
      if r.month_max_size > 0 {
        fmt = String(fmt[fmt.startIndex..<posb.lowerBound] + get_abmon(Int(tm.tm_mon)) +
                     String(repeating: " ", count: r.padding_for_month[Int(tm.tm_mon)]) + fmt[posb.upperBound...])
      }
    }

      let x : String = withUnsafeTemporaryAllocation(of: CChar.self, capacity: 80) { str in
        var tmx = tm
        let n = strftime(str.baseAddress!, 80, fmt, &tmx)
        let m = str[0..<n].map { UInt8($0) }
        return String(decoding: m, as: UTF8.self)
      }
      return x

  }

  func printtime(_ ftime : time_t) {
 //   char longstring[80];
//    static time_t now = 0;
//    const char *format;
//    static int d_first = -1;

    var format : String
    let SIXMONTHS = ((365 / 2) * 86400)
    if let fmt = options.f_timeformat {  /* user specified format */
      format = fmt
    }
    else if options.f_sectime {
      /* mmm dd hh:mm:ss yyyy || dd mmm hh:mm:ss yyyy */
      format = options.d_first ? "%e %b %T %Y" : "%b %e %T %Y";
    }
    else if (ftime + SIXMONTHS > options.my_now && ftime < options.my_now + (unix2003_compat ? 1 : SIXMONTHS)) {
      /* mmm dd hh:mm || dd mmm hh:mm */
      format = options.d_first ? "%e %b %R" : "%b %e %R";
    }
    else {
      /* mmm dd  yyyy || dd mmm  yyyy */
      format = options.d_first ? "%e %b  %Y" : "%b %e  %Y";
    }
    var ftimex = ftime
    let lt = localtime(&ftimex)
    let longstring = ls_strftime(format, lt?.pointee)
    print(longstring, terminator: " ")
  }

  @discardableResult func printtype(_ mode : FileType, _ perm : FilePermissions) -> Int {

    if (options.f_slash) {
      if mode == .directory {
        print("/", terminator: "")
        return 1
      }
      return 0
    }

    switch mode {
      case .directory:
        print("/", terminator: "")
        return 1
      case .fifo:
        print("|", terminator: "")
        return 1
      case .symbolicLink:
        print("@", terminator: "")
        return 1
      case .socket:
        print("=", terminator: "")
        return 1
      case .whiteOut:
        print("%", terminator: "")
        return 1
      default:
        break
    }

    if perm.contains(.groupExecute) || perm.contains(.otherExecute) || perm.contains(.ownerExecute) {
      print("*", terminator: "")
      return 1
    }
    return 0
  }
  

  
  func printcolor_termcap(_ c : Colors) {
    //    char *ansiseq;
    
    if r.colors[c.rawValue].bold {
      tputs(r.enter_bold, 1, putch)
    }
    
    if r.colors[c.rawValue].num[0] != -1 {
      if let k = r.ansi_fgcol, let ansiseq = tgoto(k, 0, Int(r.colors[c.rawValue].num[0])) {
        tputs(ansiseq, 1, putch);
      }
    }
    // FIXME: this business with Self.colors and c.rawValue are ugly
    if r.colors[c.rawValue].num[1] != -1 {
      if let k = r.ansi_bgcol, let ansiseq = tgoto(k, 0, Int(r.colors[c.rawValue].num[1])) {
        tputs(ansiseq, 1, putch);
      }
    }
  }
  
  func printcolor_ansi(_ c : Colors) {

    var op = "\u{1b}["
    if r.colors[c.rawValue].bold {
      op.append("1")
    }
    if r.colors[c.rawValue].num[0] != -1 {
      op.append(";3")
      op.append(String(r.colors[c.rawValue].num[0]))
    }
    if r.colors[c.rawValue].num[1] != -1 {
      op.append(";4")
      op.append(String(r.colors[c.rawValue].num[1]))
    }
    print("m", terminator: "")
  }
  
  func printcolor(_ c : Colors) {
    if explicitansi {
      printcolor_ansi(c);
    }
    else {
      printcolor_termcap(c);
    }
  }
  
  func colortype(_ ft : FileType, _ mode : FilePermissions, _ flags : FileFlags) -> Bool {
    switch ft {
      case .directory:
        if mode.contains(.otherWrite) {
          if mode.contains( .saveText) {
            printcolor(.WSDIR)
          }
          else {
            printcolor(.WDIR)
          }
        }
        else {
          printcolor(.DIR)
        }
        return true
      case .symbolicLink:
        printcolor(.LNK)
        return true
      case .socket:
        printcolor(.SOCK)
        return true
      case .fifo:
        printcolor(.FIFO)
        return true
      case .blockDevice:
        printcolor(.BLK)
        return true
      case .characterDevice:
        printcolor(.CHR)
        return true
      default:
        break
    }
    if mode.containsAny(of: [.ownerExecute, .groupExecute, .otherExecute]) {
      if mode.contains(.setUserID) {
        printcolor(.SUID)
      }
      else if mode.contains(.setGroupID) {
        printcolor(.SGID)
      }
      else {
        printcolor(.EXEC)
      }
      return true
    }
    
    if flags.contains(.SF_DATALESS) {
      printcolor(.DATALESS)
      return true
    }
    
    return false
  }
  
  func parsecolors(_ csx : String?) {
    /*    int i;
     int j;
     size_t len;
     char c[2];
     */
    var legacy_warn = false
    let cs = Array(csx ?? "") // LSCOLORS not set
    let len = cs.count
    // FIXME: this is the wrong way to get the number of colors
    for i in 0 ..< Colors.NUMCOLORS.rawValue {

      // FIXME: not happy about colors being a static variable
      r.colors[i].bold = false
      var c : [Character] = ["\0", "\0"]
      if len <= 2 * i {
        c[0] = Self.defcolors[2 * i]
        c[1] = Self.defcolors[2 * i + 1]
      } else {
        c[0] = cs[2 * i];
        c[1] = cs[2 * i + 1];
      }
      
      for j in [0, 1] {
        /* Legacy colours used 0-7 */
        if let x = Array("01234567").firstIndex(of: c[j]) {
          r.colors[i].num[j] = x
          if (!legacy_warn) {
            warnx("LSCOLORS should use characters a-h instead of 0-9 (see the manual page)")
          }
          legacy_warn = true
        } else if let n = Array("abcdefg").firstIndex(of: c[j]) {
          r.colors[i].num[j] = n
        }
        else if let n = Array("ABCDEFG").firstIndex(of: c[j]) {
          r.colors[i].num[j] = n
          r.colors[i].bold = true
        } else if (c[j].lowercased() == "x") {
          r.colors[i].num[j] = -1
        }
        else {
          warnx("invalid character '\(c[j])' in LSCOLORS env var")
          r.colors[i].num[j] = -1
        }
      }
    }
  }
  
  
  func printlink(_ p : FTSEntry) {
    var name : String
    
    if p.level == CMigration.FTS_ROOTLEVEL {
      name = p.name
    }
    else {
      name = "\(p.parent!.accpath)/\(p.name!)"
    }
    
    var path : String
    do {
      path = try readlink(name)
    } catch(let e) {
      errno = e.code
      warn("\nls: \(name)")
      return;
    }
    print(" -> ", terminator: "")
    printname(path)
  }
  
  func printsize(_ width : Int, _ bytes : UInt) {

    var buf : String
    
    if (options.f_humanval) {
      /*
       * Reserve one space before the size and allocate room for
       * the trailing '\0'.
       */
      
      buf = humanize_number(HUMANVALSTR_LEN, Int(bytes), "",nil, [.b, .nospace, .decimal] ) ?? ""
    } else if (options.f_thousands) {    /* with commas */
      buf = cFormat("%'lld", bytes)
    } else {
      buf = String(bytes)
    }
    let b2 = String(repeating: " ", count: max(0, width - buf.count)) + buf
    print(b2, terminator: " ")
  }
